"""Build the small PDFs the integration tests run against, deterministically.

    pdm run python tests/fixtures/build_pdfs.py            # rewrite tests/fixtures/pdfs/
    pdm run python tests/fixtures/build_pdfs.py --check    # fail if the committed PDFs are stale

``good.pdf`` is a real PDF/A-2b file (veraPDF passes it) that also carries the PDF/X-4 identity ``proof-pdf``
checks: an A6 card with 3 mm bleed, page boxes, ``/Trapped``, a ``GTS_PDFX`` output intent and the XMP version key.
Every other file is that file with exactly one thing wrong, so a test can say which check must notice it.
The ICC profile is generated by Pillow (littleCMS), so nothing third-party is vendored. The files are not a certified
PDF/X-4 deliverable: ``proof-pdf`` checks the X-4 identity, it does not validate the whole standard.
"""

import argparse
import pathlib
import sys
import zlib

import pikepdf
from PIL import ImageCms

OUT = pathlib.Path(__file__).parent / "pdfs"

MM = 72.0 / 25.4
TRIM_W, TRIM_H, BLEED = 105.0 * MM, 148.0 * MM, 3.0 * MM
MEDIA_W, MEDIA_H = TRIM_W + 2 * BLEED, TRIM_H + 2 * BLEED

XMP = (
    '<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>'
    '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">'
    '<rdf:Description rdf:about="" xmlns:pdfaid="http://www.aiim.org/pdfa/ns/id/">'
    "<pdfaid:part>2</pdfaid:part><pdfaid:conformance>B</pdfaid:conformance></rdf:Description>"
    '<rdf:Description rdf:about="" xmlns:pdfxid="http://www.npes.org/pdfx/ns/id/">'
    "<pdfxid:GTS_PDFXVersion>PDF/X-4</pdfxid:GTS_PDFXVersion></rdf:Description>"
    # PDF/A requires any non-predefined namespace to be described; this declares the PDF/X identity schema.
    '<rdf:Description rdf:about="" xmlns:pdfaExtension="http://www.aiim.org/pdfa/ns/extension/"'
    ' xmlns:pdfaSchema="http://www.aiim.org/pdfa/ns/schema#" xmlns:pdfaProperty="http://www.aiim.org/pdfa/ns/property#">'
    '<pdfaExtension:schemas><rdf:Bag><rdf:li rdf:parseType="Resource">'
    "<pdfaSchema:schema>PDF/X ID Schema</pdfaSchema:schema>"
    "<pdfaSchema:namespaceURI>http://www.npes.org/pdfx/ns/id/</pdfaSchema:namespaceURI>"
    "<pdfaSchema:prefix>pdfxid</pdfaSchema:prefix>"
    '<pdfaSchema:property><rdf:Seq><rdf:li rdf:parseType="Resource">'
    "<pdfaProperty:name>GTS_PDFXVersion</pdfaProperty:name><pdfaProperty:valueType>Text</pdfaProperty:valueType>"
    "<pdfaProperty:category>internal</pdfaProperty:category>"
    "<pdfaProperty:description>ID of PDF/X standard</pdfaProperty:description>"
    "</rdf:li></rdf:Seq></pdfaSchema:property></rdf:li></rdf:Bag></pdfaExtension:schemas></rdf:Description>"
    "</rdf:RDF></x:xmpmeta>"
    '<?xpacket end="w"?>'
).encode()

GOOD_CONTENT = b"0.9 g 0 0 %f %f re f 0.2 g %f %f %f %f re f" % (
    MEDIA_W,
    MEDIA_H,
    BLEED + 20,
    BLEED + 20,
    120,
    120,
)


def _icc() -> bytes:
    """sRGB from littleCMS: version lowered to 4.3 (PDF/A-2 allows 2.x and up to 4.3), creation date cleared."""
    data = bytearray(ImageCms.ImageCmsProfile(ImageCms.createProfile("sRGB")).tobytes())
    data[8:12] = bytes([4, 0x30, 0, 0])
    data[24:36] = bytes(12)  # the header's creation timestamp would make every build differ
    return bytes(data)


def build(
    content: bytes = GOOD_CONTENT,
    *,
    resources: pikepdf.Dictionary | None = None,
    boxes: dict | None = None,
    output_intent: bool = True,
    xmp: bool = True,
    trapped: bool = True,
    group_cs: str | None = None,
    pdf: pikepdf.Pdf | None = None,
) -> pikepdf.Pdf:
    """The good card, with any one part switched off or swapped."""
    pdf = pdf or pikepdf.new()
    if boxes is None:
        boxes = {
            "MediaBox": [0, 0, MEDIA_W, MEDIA_H],
            "TrimBox": [BLEED, BLEED, BLEED + TRIM_W, BLEED + TRIM_H],
            "BleedBox": [0, 0, MEDIA_W, MEDIA_H],
        }
    page = pikepdf.Dictionary(
        Type=pikepdf.Name.Page,
        Contents=pdf.make_stream(content),
        Resources=resources if resources is not None else pikepdf.Dictionary(),
        **boxes,
    )
    if group_cs is not None:
        page["/Group"] = pikepdf.Dictionary(S=pikepdf.Name.Transparency, CS=pikepdf.Name(f"/{group_cs}"))
    pdf.pages.append(pikepdf.Page(pdf.make_indirect(page)))
    if output_intent:
        profile = pdf.make_stream(zlib.compress(_icc()))
        profile["/N"] = 3
        profile["/Alternate"] = pikepdf.Name.DeviceRGB
        profile["/Filter"] = pikepdf.Name.FlateDecode
        dest = pdf.make_indirect(profile)
        # PDF/X-4 wants a GTS_PDFX intent and veraPDF only counts a GTS_PDFA1 one, so a dual file carries both,
        # sharing one profile (which PDF/A-2 allows).
        pdf.Root["/OutputIntents"] = pikepdf.Array(
            [
                pdf.make_indirect(
                    pikepdf.Dictionary(
                        Type=pikepdf.Name.OutputIntent,
                        S=pikepdf.Name(f"/{subtype}"),
                        OutputConditionIdentifier=pikepdf.String("sRGB IEC61966-2.1"),
                        RegistryName=pikepdf.String("http://www.color.org"),
                        Info=pikepdf.String("sRGB built-in"),
                        DestOutputProfile=dest,
                    )
                )
                for subtype in ("GTS_PDFX", "GTS_PDFA1")
            ]
        )
    if xmp:
        metadata = pdf.make_stream(XMP)
        metadata["/Type"] = pikepdf.Name.Metadata
        metadata["/Subtype"] = pikepdf.Name.XML
        pdf.Root["/Metadata"] = pdf.make_indirect(metadata)
    if trapped:
        pdf.docinfo["/Trapped"] = pikepdf.Name("/False")
    return pdf


def _font(pdf: pikepdf.Pdf) -> pikepdf.Object:
    """Helvetica, not embedded, with declared widths so text boxes measure exactly (every glyph 556/1000 em)."""
    return pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.Font,
            Subtype=pikepdf.Name.Type1,
            BaseFont=pikepdf.Name("/Helvetica"),
            FirstChar=32,
            LastChar=126,
            Widths=[556] * 95,
        )
    )


def _embedded_font(pdf: pikepdf.Pdf) -> pikepdf.Object:
    """A simple font that declares an embedded program (the bytes are a stand-in: only the declaration is read)."""
    descriptor = pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.FontDescriptor,
            FontName=pikepdf.Name("/ABCDEF+Nunito"),
            FontFile2=pdf.make_stream(b"stand-in font program"),
        )
    )
    return pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.Font,
            Subtype=pikepdf.Name.TrueType,
            BaseFont=pikepdf.Name("/ABCDEF+Nunito"),
            FirstChar=32,
            LastChar=126,
            Widths=[556] * 95,
            FontDescriptor=descriptor,
        )
    )


def _type3_font(pdf: pikepdf.Pdf) -> pikepdf.Object:
    """A Type 3 font with one glyph, as a bitmap or hand-built face appears."""
    glyph = pdf.make_stream(b"600 0 d0 0 0 500 500 re f")
    return pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.Font,
            Subtype=pikepdf.Name.Type3,
            Name=pikepdf.Name("/T3"),
            FontBBox=[0, 0, 600, 500],
            FontMatrix=[0.001, 0, 0, 0.001, 0, 0],
            CharProcs=pikepdf.Dictionary(A=glyph),
            Encoding=pikepdf.Dictionary(Type=pikepdf.Name.Encoding, Differences=[65, pikepdf.Name("/A")]),
            FirstChar=65,
            LastChar=65,
            Widths=[600],
            Resources=pikepdf.Dictionary(),
        )
    )


def _type0_font(pdf: pikepdf.Pdf) -> pikepdf.Object:
    """A composite Identity-H font like LuaLaTeX writes, where code 0 is the .notdef glyph."""
    descendant = pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.Font,
            Subtype=pikepdf.Name.CIDFontType2,
            BaseFont=pikepdf.Name("/ABCDEF+Nunito"),
            DW=600,
            FontDescriptor=pikepdf.Dictionary(Type=pikepdf.Name.FontDescriptor, Ascent=1000, Descent=-250),
        )
    )
    return pdf.make_indirect(
        pikepdf.Dictionary(
            Type=pikepdf.Name.Font,
            Subtype=pikepdf.Name.Type0,
            BaseFont=pikepdf.Name("/ABCDEF+Nunito"),
            Encoding=pikepdf.Name("/Identity-H"),
            DescendantFonts=[descendant],
        )
    )


def _image(pdf: pikepdf.Pdf, *, width: int, height: int, space: pikepdf.Object, components: int) -> pikepdf.Object:
    image = pdf.make_stream(zlib.compress(b"\x80" * (width * height * components)))
    image["/Type"] = pikepdf.Name.XObject
    image["/Subtype"] = pikepdf.Name.Image
    image["/Width"], image["/Height"], image["/BitsPerComponent"] = width, height, 8
    image["/ColorSpace"] = space
    image["/Filter"] = pikepdf.Name.FlateDecode
    return pdf.make_indirect(image)


def _with_image(name: str, *, size: int, space: pikepdf.Object, components: int, placed_pt: float) -> pikepdf.Pdf:
    pdf = pikepdf.new()
    image = _image(pdf, width=size, height=size, space=space, components=components)
    content = GOOD_CONTENT + b" q %f 0 0 %f %f %f cm /Im1 Do Q" % (placed_pt, placed_pt, BLEED + 20, BLEED + 20)
    return build(content, resources=pikepdf.Dictionary(XObject=pikepdf.Dictionary(Im1=image)), pdf=pdf)


def _with_text(
    stream: bytes,
    *,
    overprint: bool = False,
    size: float = 12,
    at: tuple[float, float] | None = None,
    prefix: bytes = b"",
    type0: bool = False,
    kind: str = "plain",
) -> pikepdf.Pdf:
    pdf = pikepdf.new()
    makers = {"plain": _font, "embedded": _embedded_font, "type3": _type3_font}
    font = _type0_font(pdf) if type0 else makers[kind](pdf)
    resources = pikepdf.Dictionary(Font=pikepdf.Dictionary(F1=font))
    if overprint:
        resources["/ExtGState"] = pikepdf.Dictionary(GS1=pikepdf.Dictionary(OP=True, op=True))
        stream = b"/GS1 gs " + stream
    x, y = at or (BLEED + 20, 300)  # clear of the dark square GOOD_CONTENT paints low on the page
    return build(
        GOOD_CONTENT + prefix + b" BT /F1 %f Tf %f %f Td " % (size, x, y) + stream + b" ET",
        resources=resources,
        pdf=pdf,
    )


def _with_spot(name: str) -> pikepdf.Pdf:
    space = pikepdf.Array([pikepdf.Name.Separation, pikepdf.Name(f"/{name}"), pikepdf.Name.DeviceCMYK, _tint(name)])
    content = GOOD_CONTENT + b" /CS1 cs 1 scn %f %f 60 60 re f" % (BLEED + 160, BLEED + 20)
    return build(content, resources=pikepdf.Dictionary(ColorSpace=pikepdf.Dictionary(CS1=space)))


def _tint(name: str) -> pikepdf.Dictionary:
    """A tint transform for the Separation (type 2 exponential function from white to a CMYK ink)."""
    return pikepdf.Dictionary(FunctionType=2, Domain=[0, 1], C0=[0, 0, 0, 0], C1=[0, 1, 1, 0], N=1)


def _transparent(group_cs: str | None) -> pikepdf.Pdf:
    resources = pikepdf.Dictionary(ExtGState=pikepdf.Dictionary(GS1=pikepdf.Dictionary(ca=0.5, CA=0.5)))
    content = GOOD_CONTENT + b" /GS1 gs 0.5 g %f %f 80 80 re f" % (BLEED + 150, BLEED + 150)
    return build(content, resources=resources, group_cs=group_cs)


def _multi_page(extra: list[tuple[float, float]]) -> pikepdf.Pdf:
    """The good card followed by pages of the given finished sizes in mm (each centred in a 3 mm bleed)."""
    pdf = build()
    for width_mm, height_mm in extra:
        w, h = width_mm * MM, height_mm * MM
        boxes = {
            "MediaBox": [0, 0, w + 2 * BLEED, h + 2 * BLEED],
            "TrimBox": [BLEED, BLEED, BLEED + w, BLEED + h],
            "BleedBox": [0, 0, w + 2 * BLEED, h + 2 * BLEED],
        }
        page = pikepdf.Dictionary(
            Type=pikepdf.Name.Page,
            Contents=pdf.make_stream(b"0.9 g 0 0 10 10 re f"),
            Resources=pikepdf.Dictionary(),
            **boxes,
        )
        pdf.pages.append(pikepdf.Page(pdf.make_indirect(page)))
    return pdf


def fixtures() -> dict[str, pikepdf.Pdf | bytes]:
    good = build()
    a5 = {
        "MediaBox": [0, 0, 148 * MM, 210 * MM],
        "TrimBox": [0, 0, 148 * MM, 210 * MM],
        "BleedBox": [0, 0, 148 * MM, 210 * MM],
    }
    return {
        # Passes every layer, including veraPDF PDF/A-2b.
        "good": good,
        # What a default LaTeX build looks like: boxes and metadata missing, no output intent.
        "plain": build(boxes={"MediaBox": [0, 0, MEDIA_W, MEDIA_H]}, output_intent=False, xmp=False, trapped=False),
        # Good in every way but the trim size: an A5 page where an A6 card was expected.
        "wrong-size": build(boxes=a5),
        # PDF/A-clean (sRGB intent) with a DeviceRGB raster: the colour-space check must fire.
        "rgb-image": _with_image("rgb", size=500, space=pikepdf.Name.DeviceRGB, components=3, placed_pt=100),
        # A 4x4 grey raster stretched over 100 pt: far below any print resolution.
        "low-dpi-image": _with_image("low", size=4, space=pikepdf.Name.DeviceGray, components=1, placed_pt=100),
        # Solid 400% ink: above the 300% ceiling. (DeviceCMYK without a CMYK intent also fails PDF/A.)
        "heavy-ink": build(GOOD_CONTENT + b" 1 1 1 1 k 30 30 80 80 re f"),
        # Cyan text under overprint: not K-only, and overprint on non-K content.
        "cyan-text": _with_text(b"1 0 0 0 k (cyan) Tj", overprint=True),
        # 100% K text under overprint: the normal case, which must pass --k-only-text cleanly.
        "black-text": _with_text(b"0 0 0 1 k (black) Tj", overprint=True),
        # Small text in a built black, which mis-registers.
        "rich-black-text": _with_text(b"0.6 0.5 0.4 0.9 k (rich) Tj"),
        # A character the font has no glyph for: code 0 in an Identity-H font is .notdef, printed as a box.
        "notdef-text": _with_text(b"<00410000> Tj", type0=True),
        # 4 pt text, below any sensible floor.
        "small-text": _with_text(b"0 g (tiny) Tj", size=4),
        # A zero-width stroke, the thinnest line the device can draw.
        "hairline": build(GOOD_CONTENT + b" 0 w 40 40 m 200 40 l S"),
        # Text one millimetre inside the trim edge.
        "edge-text": _with_text(b"0 g (edge) Tj", at=(BLEED + 1 * MM, 200)),
        # Mid-grey text on a slightly lighter panel: a small L* difference.
        "low-contrast": _with_text(
            b"0.8 g (faint) Tj",
            prefix=b" 0.9 g %f %f 200 60 re f" % (BLEED + 20, BLEED + 10),
            at=(BLEED + 30, BLEED + 30),
        ),
        # Black text on bare paper: the opposite.
        "high-contrast": _with_text(b"0 g (clear) Tj"),
        # White text set to overprint: it adds no ink and vanishes on press.
        "white-overprint": _with_text(b"1 g (hidden) Tj", overprint=True),
        # Text in an embedded font: the fonts check passes.
        "embedded-text": _with_text(b"0 g (embedded) Tj", kind="embedded"),
        # Text in a Type 3 font: a warning.
        "type3-text": _with_text(b"0 g (A) Tj", kind="type3"),
        # A Pantone spot ink, and the registration colour used as if it were artwork.
        "spot-ink": _with_spot("PANTONE 185 C"),
        "registration-spot": _with_spot("All"),
        # Live transparency with the blend space declared RGB, matching the sRGB output intent; CMYK, mismatching it;
        # and not declared at all.
        "transparent-matching": _transparent("DeviceRGB"),
        "transparent-mismatch": _transparent("DeviceCMYK"),
        "transparent-undeclared": _transparent(None),
        # A page of another size after the card, and a three-page file for a multiple-of-four rule.
        "two-sizes": _multi_page([(148, 210)]),
        "three-pages": _multi_page([(105, 148), (105, 148)]),
        # PDF/A metadata but no output intent: veraPDF fails on DeviceGray, and proof-pdf adds a hint.
        "no-output-intent": build(output_intent=False),
    }


def render() -> dict[str, bytes]:
    """Every fixture as bytes, deterministically."""
    out: dict[str, bytes] = {}
    scratch = OUT.parent / ".build"
    scratch.mkdir(exist_ok=True)
    try:
        for name, pdf in fixtures().items():
            path = scratch / f"{name}.pdf"
            assert isinstance(pdf, pikepdf.Pdf)
            pdf.save(
                path,
                deterministic_id=True,
                min_version="1.7",
                compress_streams=False,
                object_stream_mode=pikepdf.ObjectStreamMode.disable,
            )
            out[name] = path.read_bytes()
        out["corrupt"] = out["good"][: len(out["good"]) // 2]  # truncated mid-file
    finally:
        for f in scratch.glob("*.pdf"):
            f.unlink()
        scratch.rmdir()
    return out


def main() -> int:
    parser = argparse.ArgumentParser(description=(__doc__ or "").splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if the committed fixtures differ from a rebuild")
    args = parser.parse_args()
    built = render()
    if args.check:
        stale = [
            n
            for n, data in built.items()
            if not (OUT / f"{n}.pdf").is_file() or (OUT / f"{n}.pdf").read_bytes() != data
        ]
        stale += [p.stem for p in OUT.glob("*.pdf") if p.stem not in built]
        if stale:
            print(f"stale fixtures: {', '.join(sorted(stale))}; run build_pdfs.py", file=sys.stderr)
            return 1
        return 0
    OUT.mkdir(parents=True, exist_ok=True)
    for name, data in built.items():
        (OUT / f"{name}.pdf").write_bytes(data)
    print(f"wrote {len(built)} PDFs to {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
